#!/usr/bin/env python3
"""Build a small static deployment directory for Vercel or other CDNs."""
import runpy
import shutil
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
runpy.run_path(str(ROOT / 'scripts/build_homepage.py'), run_name='__main__')
SOURCE = ROOT / 'dist' if (ROOT / 'dist/index.html').exists() else ROOT
OUTPUT = ROOT / 'public'
# This directory is generated by this script and never contains editable source.
if OUTPUT.is_symlink():
    raise RuntimeError('Refusing to overwrite a symlink at the output directory')
if OUTPUT.exists():
    shutil.rmtree(OUTPUT)
OUTPUT.mkdir()
FILES = (
    'index.html', '404.html', 'robots.txt', 'sitemap.xml',
    'site/style.css', 'site/portrait-480.jpg',
)
for relative in FILES:
    source = SOURCE / relative
    destination = OUTPUT / relative
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(source, destination)
size = sum(p.stat().st_size for p in OUTPUT.rglob('*') if p.is_file())
print(f'Exported {len(FILES)} files ({size:,} bytes) to {OUTPUT}')
